UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"A compromised application can alter or replace logs, approvals and retest records while preserving a plausible story.","customer_symptom":"A user or operator may observe a compromised application can alter or replace logs, approvals and retest records while preserving a plausible story; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious user, compromised dependency, unsafe model behaviour, or operator error can exploit or trigger the condition in a compromised application can alter or replace logs, approvals and retest records while preserving a plausible story, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["agent","model context","tools or downstream systems","customer evidence"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["agents requiring defensible evidence"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The test crosses the boundary between agents requiring defensible evidence and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If a compromised application can alter or replace logs, approvals and retest records while preserving a plausible story, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-091 evidence format, signing, storage, verification or key-management change","ARL-KB-091 new consequential evidence source or audit chain","ARL-KB-091 tampering, deletion, replacement or integrity-verification failure","ARL-KB-091 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='f9729fac55d208faba1bd60526d1b894be1ee4d642117f487e9af6cbd0895a0f', updated_at='2026-08-06' WHERE id='ARL-KB-091';
UPDATE risk_knowledge_checks SET objective='Determine whether consequential evidence can be deleted, inserted, reordered or replaced without detectable integrity failure.', method='Using owner-authorised synthetic evidence, test deletion, insertion, reordering, record modification and complete-chain replacement. Verify an independent integrity mechanism detects each alteration and that verification does not depend solely on the application that produced the evidence.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-091 assessed system, version, environment and scope for Evidence can be rewritten without detection","ARL-KB-091 control configuration or source location showing how reduce the likelihood and impact of evidence can be rewritten without detection and make the remaining risk visible.","ARL-KB-091 positive and abuse inputs with expected and observed outputs for agent and model context","ARL-KB-091 policy, authorization, tool or audit events proving whether the tested evidence can be rewritten without detection path executed","ARL-KB-091 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-091 passes only when “Evidence can be rewritten without detection” is not reproducible through the documented abuse cases, the valid workflow remains bounded to agent and model context, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-091 fails when a compromised application can alter or replace logs, approvals and retest records while preserving a plausible story, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-091 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='c348bb43bbee344314c29cec1d738fc5f9b4943faef7391366f9028929635b9d', updated_at='2026-08-06' WHERE entry_id='ARL-KB-091';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of evidence can be rewritten without detection and make the remaining risk visible.', recommended_remediation='Sign canonical evidence with protected keys, anchor digests externally, use append-only storage and separate duties for verification.', default_owner='Assurance and security owner', priority='P0', implementation_principles_json='["ARL-KB-091: Protect canonical evidence using cryptographic integrity controls with keys outside the producing application''s authority.","ARL-KB-091: Anchor evidence digests or checkpoints independently where defensible reconstruction is required.","ARL-KB-091: Prefer append-only evidence storage and separate evidence production from verification authority."]', monitoring='For ARL-KB-091, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Assurance and security owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-091 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-091: “Evidence can be rewritten without detection” is no longer reproducible against the exact remediated version.","ARL-KB-091: Authorised in-scope use completes successfully, remains within the documented asset scope for evidence can be rewritten without detection, and produces no unintended side effect.","ARL-KB-091: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-091: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='c9b1f64195d997edabba8847d0090efe5316dd08f5893ce04ba9501bef2e6e28', updated_at='2026-08-06' WHERE entry_id='ARL-KB-091';
