UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Critical denials, approval abuse, data export or drift events are recorded but nobody acts.","customer_symptom":"A user or operator may observe critical denials, approval abuse, data export or drift events are recorded but nobody acts; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious user, compromised dependency, unsafe model behaviour, or operator error can exploit or trigger the condition in critical denials, approval abuse, data export or drift events are recorded but nobody acts, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["agent","model context","tools or downstream systems","customer evidence"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["production agents"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The test crosses the boundary between production agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If critical denials, approval abuse, data export or drift events are recorded but nobody acts, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-092 alert route, severity, owner, escalation or runbook change","ARL-KB-092 new critical runtime, approval, export or drift signal","ARL-KB-092 missed, delayed or unowned security-alert evidence","ARL-KB-092 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='bcb6cb49f06b6a14b561cab82dfe59a325bee289c97a999b64dcda5f3e0d8326', updated_at='2026-08-06' WHERE id='ARL-KB-092';
UPDATE risk_knowledge_checks SET objective='Determine whether security-relevant agent alerts reach an accountable owner and trigger a tested acknowledgement, escalation, containment and evidence-preservation process.', method='Trigger representative synthetic alerts for critical denial, approval abuse, abnormal export and configuration or behavioural drift. Measure delivery, acknowledgement, escalation, containment and evidence preservation against documented routes and response expectations.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-092 assessed system, version, environment and scope for Alerts have no tested owner or response","ARL-KB-092 control configuration or source location showing how reduce the likelihood and impact of alerts have no tested owner or response and make the remaining risk visible.","ARL-KB-092 positive and abuse inputs with expected and observed outputs for agent and model context","ARL-KB-092 policy, authorization, tool or audit events proving whether the tested alerts have no tested owner or response path executed","ARL-KB-092 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-092 passes only when “Alerts have no tested owner or response” is not reproducible through the documented abuse cases, the valid workflow remains bounded to agent and model context, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-092 fails when critical denials, approval abuse, data export or drift events are recorded but nobody acts, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-092 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='1bfd57762ad6016ff2c0a81861e539049ad586f29cd7ea967f761fcd756efc88', updated_at='2026-08-06' WHERE entry_id='ARL-KB-092';
