UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Agents call themselves or each other repeatedly, causing cost, duplicate actions or service degradation.","customer_symptom":"A user or operator may observe agents call themselves or each other repeatedly, causing cost, duplicate actions or service degradation; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious user, compromised dependency, unsafe model behaviour, or operator error can exploit or trigger the condition in agents call themselves or each other repeatedly, causing cost, duplicate actions or service degradation, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tool endpoints and downstream systems","financial, administrative or state-changing actions","agent","model context","tools or downstream systems","customer evidence"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["autonomous or multi-agent systems"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The test crosses the boundary between autonomous or multi-agent systems and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If agents call themselves or each other repeatedly, causing cost, duplicate actions or service degradation, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-096 planner, delegation, retry, timeout or termination-policy change","ARL-KB-096 new autonomous or multi-agent recursion path","ARL-KB-096 infinite loop, repeated-state or duplicate-side-effect evidence","ARL-KB-096 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='fbba38152e0ac287f2c393cff802833dd97839213096712a3ea9abeb67a7e39b', updated_at='2026-08-06' WHERE id='ARL-KB-096';
