d hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-097 critical dependency, timeout, fallback, queue or recovery-path change","ARL-KB-097 new provider, identity, vector, storage or tool dependency","ARL-KB-097 unsafe fallback, corrupted recovery or prolonged-outage evidence","ARL-KB-097 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='7a7df611ebe48ecee6ded05fefd89efc1258871785e0d2cda1fe340bae568dc2', updated_at='2026-08-06' WHERE id='ARL-KB-097';
